            function migrate(st) {
                if (!st.cam)
                    st.cam = {
                        x: -60,
                        y: -40,
                        z: .8
                    };
                st.items.forEach(i => {
                    if (i.parent === undefined)
                        i.parent = null;
                    if (i.seed === undefined)
                        i.seed = Math.random() * 1e9 | 0
                }
                );
                if (!st.pinColor)
                    st.pinColor = "#c3161c";
                st.ui = Object.assign({
                    tools: true,
                    help: true,
                    mini: true,
                    top: true
                }, st.ui || {});
                if (st.sound === undefined)
                    st.sound = true;
                return st
            }

