                        x.fillText("MOTOBIP", 44, 246);
                        metal(x, 370, 70, 64, 64, 32);
                        x.fillStyle = "#2a2d31";
                        x.beginPath();
                        x.arc(402, 102, 20, 0, 7);
                        x.fill();
                        metal(x, 366, 170, 30, 30, 15);
                        metal(x, 408, 170, 30, 30, 15);
                        noise(x, W, H, 6, it.seed);
                        return {
                            c,
                            box: {
                                x: 0,
                                y: 0,
                                w: W,
                                h: H
                            }
                        }
