            CONT.mod_dial.ctl = (it, z, ev) => {
                const cl = modCluster(it)
                  , ang = () => Math.atan2(z.fx - .5, -(z.fy - .5)) * 180 / Math.PI;
                if (ev.type === "down") {
                    it._da = null;
                    it._acc = 0;
                    return
                }
                if (ev.type === "move") {
                    if (Math.hypot(z.fx - .5, z.fy - .5) < .07)
                        return;
                    const a = ang();
                    if (it._da == null) {
                        it._da = a;
                        return
                    }
                    let d = a - it._da;
                    d = ((d + 540) % 360) - 180;
                    it._da = a;
                    it._acc = (it._acc || 0) + d;
                    let ch = false;
                    while (Math.abs(it._acc) >= 27) {
                        const s = Math.sign(it._acc);
                        it._acc -= s * 27;
                        const nv = clamp((it.val || 0) + s, 0, 10);
                        if (nv !== (it.val || 0)) {
                            modSetV(it, nv, cl, true);
                            play("tick");
                            ch = true
                        }
                    }
                    if (ch)
                        modCheck(cl);
                    return
                }
                if (ev.type === "step") {
                    if (ev.src === "drag")
                        return;
                    modSetV(it, clamp((it.val || 0) + ev.d, 0, 10), cl, true);
                    play("tick");
                    modCheck(cl);
                    return
                }
                if (ev.type === "click")
                    showRack(it)
            }
