                bimetalica: ["Bimetálica (2)", "#e0bd62", "#8a6a24", 2],
                furada: ["Furada (5)", "#d8b25a", "#7a5a1a", 5],
                antiga: ["Antiga, gasta", "#a88f5a", "#4d3f22", 0],
