            function tryUnscrew(sd) {
                const h = itemH(sd)
                  , tip = localToWorld(sd, 0, h * .47);
                for (const pl of S.items) {
                    if (pl.type !== "cont" || pl.kind !== "placa" || pl.solved || isHidden(pl))
                        continue;
                    const ph = itemH(pl);
                    pl.screws = pl.screws || [1, 1, 1, 1];
                    for (let i = 0; i < 4; i++) {
                        if (!pl.screws[i])
                            continue;
                        const sp = localToWorld(pl, (SCR_POS[i][0] - .5) * pl.w, (SCR_POS[i][1] - .5) * ph);
                        if (Math.hypot(sp.x - tip.x, sp.y - tip.y) < Math.max(22, pl.w * .09 * pl.scale)) {
                            snap();
                            pl.screws[i] = 0;
                            play("screw");
                            const s = screenOf(sp);
                            flakes(s.x, s.y, "#c9cdd2", 6);
                            buildItem(pl);
                            if (pl.screws.every(v => !v))
                                setTimeout( () => {
                                    solveLock(pl);
                                    toast("A placa soltou!")
                                }
                                , 450);
                            save();
                            return true
                        }
                    }
                }
                return false
            }

