            const hsl = (h, s, l, a) => `hsla(${h},${s}%,${Math.max(0, Math.min(100, l))}%,${a == null ? 1 : a})`;
            function gemDraw(x, cx, cy, R, tipo, corte, seed) {
                const [h,s,l] = GEMS[tipo] || GEMS.rubi
                  , r = rng(seed);
                x.save();
                x.shadowColor = "rgba(0,0,0,.45)";
                x.shadowBlur = R * .25;
                x.shadowOffsetY = R * .12;
                const facet = (pts, ll, a) => {
                    x.beginPath();
                    pts.forEach( ([px,py], i) => i ? x.lineTo(px, py) : x.moveTo(px, py));
                    x.closePath();
                    x.fillStyle = hsl(h, s, ll, a);
                    x.fill()
                }
                ;
                if (corte === "bruto") {
                    const n = 7;
                    const P = [];
                    for (let i = 0; i < n; i++) {
                        const a = i / n * 6.283 + r() * .4
                          , rr = R * (.7 + r() * .35);
                        P.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr * .85])
                    }
                    facet(P, l - 8);
                    x.shadowColor = "transparent";
                    for (let i = 0; i < n; i++) {
                        const j = (i + 1) % n;
                        facet([[cx + (r() - .5) * R * .3, cy + (r() - .5) * R * .3], P[i], P[j]], l - 14 + r() * 30, .85)
                    }
                } else if (corte === "cristal") {
                    const w = R * .55
                      , hh = R * 1.5;
                    const P = [[cx - w, cy + hh * .5], [cx - w, cy - hh * .2], [cx, cy - hh * .62], [cx + w, cy - hh * .2], [cx + w, cy + hh * .5]];
                    facet(P, l - 10);
                    x.shadowColor = "transparent";
                    facet([[cx - w, cy + hh * .5], [cx - w, cy - hh * .2], [cx - w * .2, cy - hh * .3], [cx - w * .2, cy + hh * .5]], l + 12, .9);
                    facet([[cx - w * .2, cy - hh * .3], [cx, cy - hh * .62], [cx + w, cy - hh * .2], [cx + w * .3, cy - hh * .25]], l + 22, .85);
                    facet([[cx + w * .3, cy - hh * .25], [cx + w, cy - hh * .2], [cx + w, cy + hh * .5], [cx + w * .3, cy + hh * .5]], l - 18, .9)
                } else if (corte === "gota") {
                    const P = [];
                    for (let i = 0; i <= 24; i++) {
                        const t = i / 24 * 6.283
                          , rr = R * (1 - .35 * Math.sin(t / 2) ** 8);
                        P.push([cx + Math.sin(t) * rr * .78, cy - Math.cos(t) * rr * (t < Math.PI * .6 || t > Math.PI * 1.4 ? 1.15 : .9)])
                    }
                    facet(P, l - 6);
                    x.shadowColor = "transparent";
                    for (let i = 0; i < 24; i += 2)
                        facet([[cx, cy], P[i], P[i + 1]], l - 10 + ((i / 2) % 3) * 14, .75);
                    facet(P.map( ([px,py]) => [cx + (px - cx) * .45, cy + (py - cy) * .45]), l + 10, .85)
                } else if (corte === "retangular") {
                    const w = R * .95
                      , hh = R * .7
                      , k = .62;
                    const O = [[cx - w, cy - hh], [cx + w, cy - hh], [cx + w, cy + hh], [cx - w, cy + hh]]
                      , I = O.map( ([px,py]) => [cx + (px - cx) * k, cy + (py - cy) * k]);
                    facet(O, l - 6);
                    x.shadowColor = "transparent";
                    [[0, 1, l + 16], [1, 2, l - 14], [2, 3, l - 20], [3, 0, l + 6]].forEach( ([a,b,ll]) => facet([O[a], O[b], I[b], I[a]], ll, .85));
                    facet(I, l + 4, .9);
                    facet(I.map( ([px,py]) => [cx + (px - cx) * .55, cy + (py - cy) * .55]), l + 14, .6)
                } else {
                    const n = 8
                      , P = []
                      , Q = [];
                    for (let i = 0; i < n; i++) {
                        const a = i / n * 6.283 - Math.PI / 8;
                        P.push([cx + Math.cos(a) * R, cy + Math.sin(a) * R]);
                        Q.push([cx + Math.cos(a + Math.PI / n) * R * .55, cy + Math.sin(a + Math.PI / n) * R * .55])
                    }
                    facet(P, l - 8);
                    x.shadowColor = "transparent";
                    for (let i = 0; i < n; i++) {
                        const j = (i + 1) % n;
                        facet([P[i], P[j], Q[i]], l - 16 + ((i * 37) % 5) * 9, .85);
                        facet([Q[i], Q[(i + n - 1) % n], P[i]], l + ((i * 53) % 4) * 8, .7)
                    }
                    facet(Q, l + 12, .95)
                }
                x.shadowColor = "transparent";
                x.fillStyle = "rgba(255,255,255,.7)";
                x.beginPath();
                x.ellipse(cx - R * .32, cy - R * .36, R * .13, R * .07, -.6, 0, 7);
                x.fill();
                x.fillStyle = "rgba(255,255,255,.4)";
                x.beginPath();
                x.arc(cx + R * .25, cy + R * .1, R * .05, 0, 7);
                x.fill();
                x.restore()
            }
