            /* ================= v37: fita VHS + TV com videocassete, CD + discman ================= */
            function pickMedia(it, accept, maxMB, done) {
                const f = document.createElement("input");
                f.type = "file";
                f.accept = accept;
                f.onchange = () => {
                    const file = f.files[0];
                    if (!file)
                        return;
                    if (file.size > maxMB * 1048576) {
                        toast(`Arquivo grande demais (máx. ${maxMB} MB). Use um vídeo curto em .webm.`);
                        return
                    }
                    if (file.size > 6 * 1048576)
                        toast("Arquivo pesado: os jogadores podem demorar pra receber");
                    const fr = new FileReader();
                    fr.onload = () => {
                        const id = uid();
                        IMG[id] = fr.result;
                        snap();
                        it.audioId = id;
                        it.mediaName = file.name;
                        done && done();
                        buildItem(it);
                        save();
                        toast("Carregado: " + file.name)
                    }
                    ;
                    fr.readAsDataURL(file)
                }
                ;
                f.click()
            }
            function insertMedia(dev, m, key) {
                if (dev[key] && itemById(dev[key])) {
                    toast("Já tem uma mídia aí dentro");
                    return
                }
                snap();
                detach(m);
                tween(m, {
                    x: dev.x,
                    y: dev.y,
                    scale: m.scale * .5
                }, {
                    dur: 300,
                    done: () => {
                        m.inside = dev.id;
                        dev[key] = m.id;
                        dev.playing = false;
                        const el = document.getElementById("it-" + m.id);
                        if (el)
                            el.classList.add("inside");
                        buildItem(dev);
                        save()
                    }
                });
                play("latch")
            }
            function ejectMedia(dev, key) {
                const m = dev[key] && itemById(dev[key]);
                if (!m)
                    return;
                snap();
                dev.playing = false;
                dev[key] = null;
                m.inside = null;
                m.scale = dev.scale;
                const p = localToWorld(dev, dev.w * .65, itemH(dev) * .25);
                m.x = dev.x;
                m.y = dev.y;
                m.z = nextZ();
                stopDevAudio(dev);
                buildItem(m).then( () => tween(m, {
                    x: p.x,
                    y: p.y
                }, {
                    dur: 400
                }));
                buildItem(dev);
                play("latch");
                save()
            }
            const elapsed = d => Math.max(0, (Date.now() - (d.playT || Date.now())) / 1000 + (d.playOff || 0));
            /* ---- VHS ---- */
