                    const led = `<div class="vled" style="left:${384 / 600 * 100}%;top:${490 / 600 * 100}%;width:${132 / 600 * 100}%;height:${32 / 600 * 100}%;font-size:${OVF(it, .045)}">${t ? (it.playing ? "▶ " + fmtT(elapsed(it) * 1000) : "■ STOP") : "--:--"}</div>`;
