            /* v44: partículas de poeira no clique + cursor "agarrando" */
            {
                const FX = {
                    cv: null,
                    x: null,
                    ps: [],
                    raf: 0,
                    dpr: 1
                };
                function fxSize() {
                    const c = FX.cv;
                    if (!c)
                        return;
                    FX.dpr = Math.min(2, devicePixelRatio || 1);
                    c.width = innerWidth * FX.dpr;
                    c.height = innerHeight * FX.dpr
                }
                function fxInit() {
                    if (FX.cv)
                        return;
                    const c = document.createElement("canvas");
                    c.id = "fxDust";
                    document.body.appendChild(c);
                    FX.cv = c;
                    FX.x = c.getContext("2d");
                    fxSize();
                    addEventListener("resize", fxSize)
                }
                const COL = [[240, 232, 212], [222, 206, 176], [168, 148, 118], [128, 110, 88], [250, 246, 236]];
                function dust(x, y) {
                    if (document.body.classList.contains("a11y-rm"))
                        return;
                    fxInit();
                    const n = 8 + (Math.random() * 4 | 0);
                    FX.ps.push({
                        ring: 1,
                        x,
                        y,
                        t: 0,
                        life: 380
                    });
                    for (let i = 0; i < n; i++) {
                        const a = Math.random() * Math.PI * 2
                          , sp = 22 + Math.random() * 60
                          , c = COL[Math.random() * COL.length | 0];
                        FX.ps.push({
                            x: x + Math.cos(a) * 3,
                            y: y + Math.sin(a) * 3,
                            vx: Math.cos(a) * sp,
                            vy: Math.sin(a) * sp * .75 - 12,
                            r: .8 + Math.random() * 1.3,
                            c,
                            a0: .55 + Math.random() * .3,
                            t: 0,
                            life: 480 + Math.random() * 360
                        })
                    }
                    if (FX.ps.length > 220)
                        FX.ps.splice(0, FX.ps.length - 220);
                    if (!FX.raf) {
                        FX.last = performance.now();
                        FX.raf = requestAnimationFrame(fxStep)
                    }
                }
                function fxStep(ts) {
                    const dt = Math.min(.05, (ts - FX.last) / 1000);
                    FX.last = ts;
                    const x = FX.x
                      , d = FX.dpr;
                    x.setTransform(1, 0, 0, 1, 0, 0);
                    x.clearRect(0, 0, FX.cv.width, FX.cv.height);
                    x.setTransform(d, 0, 0, d, 0, 0);
                    const k = Math.pow(.04, dt);
                    FX.ps = FX.ps.filter(p => {
                        p.t += dt * 1000;
                        const f = p.t / p.life;
                        if (f >= 1)
                            return false;
                        if (p.ring) {
                            x.beginPath();
                            x.arc(p.x, p.y, 3 + f * 11, 0, 7);
                            x.strokeStyle = `rgba(240,232,212,${.3 * (1 - f)})`;
                            x.lineWidth = 1.4 * (1 - f) + .3;
                            x.stroke();
                            return true
                        }
                        p.vx *= k;
                        p.vy = p.vy * k - 14 * dt;
                        p.x += p.vx * dt;
                        p.y += p.vy * dt;
                        const al = p.a0 * (1 - f) * (f < .08 ? f / .08 : 1)
                          , r = p.r * (1 + f * .6);
                        x.fillStyle = `rgba(${p.c[0]},${p.c[1]},${p.c[2]},${al})`;
                        x.beginPath();
                        x.arc(p.x, p.y, r, 0, 7);
                        x.fill();
                        return true
                    }
                    );
                    if (FX.ps.length)
                        FX.raf = requestAnimationFrame(fxStep);
                    else {
                        FX.raf = 0;
                        x.setTransform(1, 0, 0, 1, 0, 0);
                        x.clearRect(0, 0, FX.cv.width, FX.cv.height)
                    }
                }
                window.dustAt = dust;
                window.dustMote = (x, y, n=1) => {
                    if (document.body.classList.contains("a11y-rm"))
                        return;
                    fxInit();
                    for (let i = 0; i < n; i++) {
                        const a = Math.random() * Math.PI * 2
                          , sp = 8 + Math.random() * 22
                          , c = COL[Math.random() * COL.length | 0];
                        FX.ps.push({
                            x: x + (Math.random() - .5) * 10,
                            y: y + (Math.random() - .5) * 6,
                            vx: Math.cos(a) * sp,
                            vy: Math.sin(a) * sp * .5 - 6,
                            r: .6 + Math.random() * .9,
                            c,
                            a0: .3 + Math.random() * .25,
                            t: 0,
                            life: 420 + Math.random() * 300
                        })
                    }
                    if (FX.ps.length > 220)
                        FX.ps.splice(0, FX.ps.length - 220);
                    if (!FX.raf) {
                        FX.last = performance.now();
                        FX.raf = requestAnimationFrame(fxStep)
                    }
                }
                ;
                addEventListener("pointerdown", e => {
                    if (e.button > 0)
                        return;
                    dust(e.clientX, e.clientY)
                }
                , true);
                addEventListener("pointermove", () => {
                    const g = typeof drag !== "undefined" && drag && (drag.mode === "move" || drag.mode === "group");
                    if (g !== document.body.classList.contains("grabbing"))
                        document.body.classList.toggle("grabbing", !!g)
                }
                , true);
                const ug = () => document.body.classList.remove("grabbing");
                addEventListener("pointerup", ug, true);
                addEventListener("pointercancel", ug, true)
            }

