            {
                const _dh = dropHooks;
                dropHooks = function(it) {
                    try {
                        if (it && it.type === "cont" && !it.fixed) {
                            if (it.kind === "cartab") {
                                const decks = S.items.filter(o => o.type === "cont" && o.kind === "baralho" && !isHidden(o) && inRect(o, it.x, it.y, .95, .95));
                                const d = decks.find(o => o.id === it.deck) || decks[0];
                                if (d) {
                                    snap();
                                    if (!Array.isArray(d.order))
                                        d.order = [];
                                    d.order.unshift(it.code | 0);
                                    const id = it.id;
                                    play("pflip");
                                    tween(it, {
                                        x: d.x,
                                        y: d.y,
                                        rot: d.rot || 0
                                    }, {
                                        dur: 160,
                                        done: () => {
                                            removeItem(id);
                                            buildItem(d);
                                            refreshOv && refreshOv(d);
                                            save();
                                            if (typeof netFlush === "function")
                                                netFlush()
                                        }
                                    });
                                    return
                                }
                            }
                            if (it.kind === "baralho") {
                                const d = S.items.find(o => o !== it && o.type === "cont" && o.kind === "baralho" && !isHidden(o) && inRect(o, it.x, it.y, .9, .9));
                                if (d) {
                                    snap();
                                    d.order = (Array.isArray(it.order) ? it.order : []).concat(Array.isArray(d.order) ? d.order : []);
                                    S.items.forEach(c => {
                                        if (c.kind === "cartab" && c.deck === it.id)
                                            c.deck = d.id
                                    }
                                    );
                                    const id = it.id;
                                    play("pflip");
                                    tween(it, {
                                        x: d.x,
                                        y: d.y,
                                        rot: d.rot || 0
                                    }, {
                                        dur: 180,
                                        done: () => {
                                            removeItem(id);
                                            buildItem(d);
                                            refreshOv && refreshOv(d);
                                            save();
                                            if (typeof netFlush === "function")
                                                netFlush();
                                            toast("Baralhos juntados")
                                        }
                                    });
                                    return
                                }
                            }
                        }
                    } catch (e) {
                        console.warn(e)
                    }
                    return _dh(it)
                }
            }
